#include <bits/stdc++.h>
using namespace std;using C=chrono::steady_clock;int B[15][15],ME;C::time_point DEAD;int dr[4]={1,0,1,1},dc[4]={0,1,1,-1};
bool in(int r,int c){return r>=0&&r<15&&c>=0&&c<15;}int line(int r,int c,int p,int k){int n=1;for(int s=1;in(r+s*dr[k],c+s*dc[k])&&B[r+s*dr[k]][c+s*dc[k]]==p;s++)n++;for(int s=1;in(r-s*dr[k],c-s*dc[k])&&B[r-s*dr[k]][c-s*dc[k]]==p;s++)n++;return n;}bool five(int r,int c,int p){for(int k=0;k<4;k++)if(line(r,c,p,k)==5)return 1;return 0;}
bool legal(int r,int c,int p){if(!in(r,c)||B[r][c]!=-1)return 0;if(p){return 1;}B[r][c]=p;int f=0;for(int k=0;k<4;k++)f+=line(r,c,p,k)>=3;bool x=f>1;for(int k=0;k<4;k++)x|=line(r,c,p,k)>5;B[r][c]=-1;return !x;}
int eval(int r,int c,int p){B[r][c]=p;int s=five(r,c,p)?1000000:0;for(int k=0;k<4;k++){int n=line(r,c,p,k);s+=n==4?5000:n==3?300:n*4;}B[r][c]=-1;return s;}
vector<pair<int,int>> gen(int p){vector<tuple<int,int,int>>v;for(int r=0;r<15;r++)for(int c=0;c<15;c++)if(legal(r,c,p)){bool n=0;for(int x=-2;x<=2;x++)for(int y=-2;y<=2;y++)if(in(r+x,c+y)&&B[r+x][c+y]!=-1)n=1;if(n)v.push_back({-eval(r,c,p),r,c});}sort(v.begin(),v.end());vector<pair<int,int>>o;for(auto&q:v)if(o.size()<14)o.push_back({get<1>(q),get<2>(q)});return o;}
int mm(int p,int d,int a,int z){if(C::now()>=DEAD||!d)return 0;int best=-1e9;for(auto q:gen(p)){B[q.first][q.second]=p;int s=five(q.first,q.second,p)?900000:-mm(p^1,d-1,-z,-a);B[q.first][q.second]=-1;best=max(best,s);a=max(a,s);if(a>=z)break;}return best;}
int main(){ios::sync_with_stdio(0);cin.tie(0);if(!(cin>>ME))return 0;for(auto&r:B)for(int&x:r){cin>>x;if(x!=0&&x!=1)x=-1;}auto v=gen(ME);if(v.empty())v={{7,7}};for(auto q:v){B[q.first][q.second]=ME;bool w=five(q.first,q.second,ME);B[q.first][q.second]=-1;if(w){cout<<q.first<<' '<<q.second;return 0;}}for(int r=0;r<15;r++)for(int c=0;c<15;c++)if(legal(r,c,ME^1)){B[r][c]=ME^1;bool w=five(r,c,ME^1);B[r][c]=-1;if(w&&legal(r,c,ME)){cout<<r<<' '<<c;return 0;}}if(B[7][7]==-1&&ME==0&&legal(7,7,0)){cout<<"7 7";return 0;}DEAD=C::now()+chrono::milliseconds(520);pair<int,int>a=v[0];int best=-1e9;for(auto q:v){B[q.first][q.second]=ME;int s=-mm(ME^1,2,-1e9,1e9);B[q.first][q.second]=-1;if(s>best)best=s,a=q;}cout<<a.first<<' '<<a.second;}
